{
  "document_type": "lease",
  "lessor": "Beijing Shunfeng Runlin Technology and Trade Co., Ltd.",
  "lessee": "Beijing Ninetown Sky Eco-Agriculture Co., Ltd.",
  "premises_address": "south of Lianying Village, Quanying Town, Shunyi District, Beijing",
  "area": null,
  "start_date": "2010-03-01",
  "end_date": "2013-02-28",
  "rent": {
    "amount": 550000,
    "currency": "CNY",
    "period": "year"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "landlord_repairs",
      "quote": "Party B has the right and obligation to reasonably use and actively maintain and repair the premise, and Party A has the right to supervise the use of the premise to make sure it is free of any damages or losses."
    },
    {
      "type": "service_charges_limited",
      "quote": "Party B shall bear by itself the expenses for telephone and broadband internet access. Party A shall assist in the clearing and management of the daily garbage and Party B shall bear the cost."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party B fails to perform the lease due to its poor performance, it shall notify Party A in Writing one (1) month in advance. After obtaining the consent from Party A, Party B may terminate the Contract without incurring any liability."
    },
    {
      "type": "sublease_permitted",
      "quote": "Party B shall obtain Party A’s prior consent regarding temporarily building fixtures to the site within the term of this Contract, and Party B undertakes that, upon the expiration of this Contract, the fixtures shall be owned by Party A and that all temporary buildings shall be vacated."
    }
  ]
}
